1053	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, inputs trailUpdateInputs) error {
1054		return runAuthenticatedTrailAPI(ctx, errW, insecureHTTP, inputs.Repo, func(ctx context.Context, client *api.Client) error {
1055			forge, owner, repoName, err := resolveTrailRepoOrRemote(ctx, inputs.Repo)
1056			if err != nil {
1057				return err
1058			}
1059	
1060			// Determine branch.
1061			branch := inputs.Branch
1062			if branch == "" {
1063				branch, err = GetCurrentBranch(ctx)
1064				if err != nil {
1065					return fmt.Errorf("failed to determine current branch: %w", err)
1066				}
1067			}
1068	
1069			// Find the trail by branch.
1070			found, err := findTrailByBranch(ctx, client, forge, owner, repoName, branch)
1071			if err != nil {
1072				return err
1073			}
1074			if found == nil {
1075				return fmt.Errorf("no trail found for branch %q", branch)
1076			}
1077	
1078			// Interactive mode when no update flags are provided.
1079			statusStr := inputs.Status
1080			title := inputs.Title
1081			body := inputs.Body
1082			noFlags := !inputs.StatusChanged && !inputs.TitleChanged && !inputs.BodyChanged && inputs.LabelAdd == nil && inputs.LabelRemove == nil
1083			if noFlags {
1084				metadata := found.ToMetadata()
1085				// Build status options with current value as default.
1086				var statusOptions []huh.Option[string]
1087				for _, s := range trail.ValidStatuses() {
1088					if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
1089						continue
1090					}
1091					label := string(s)
1092					if s == metadata.Status {
1093						label += " (current)"
1094					}
1095					statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
1096				}
1097				statusStr = string(metadata.Status)
1098				title = metadata.Title
1099				body = metadata.Body
1100	
1101				form := NewAccessibleForm(
1102					huh.NewGroup(
1103						huh.NewSelect[string]().
1104							Title("Status").
1105							Options(statusOptions...).
1106							Value(&statusStr),
1107						huh.NewInput().
1108							Title("Title").
1109							Value(&title),
1110						huh.NewText().
1111							Title("Body").
1112							Value(&body),
1113					),
1114				)
1115				if formErr := form.Run(); formErr != nil {
1116					return handleFormCancellation(w, "Trail update", formErr)
1117				}
1118				inputs.StatusChanged = true
1119				inputs.TitleChanged = true
1120				inputs.BodyChanged = true
1121			}
1122	
1123			statusStr = strings.TrimSpace(statusStr)
1124			title = strings.TrimSpace(title)
1125			if err := validateTrailUpdateFields(trailUpdateInputs{
1126				Status:        statusStr,
1127				StatusChanged: inputs.StatusChanged,
1128				Title:         title,
1129				TitleChanged:  inputs.TitleChanged,
1130			}); err != nil {
1131				return err
1132			}
1133	
1134			// Build update request with only changed fields.
1135			updateReq := buildTrailUpdateRequest(found, trailUpdateInputs{
1136				Status:        statusStr,
1137				StatusChanged: inputs.StatusChanged,
1138				Title:         title,
1139				TitleChanged:  inputs.TitleChanged,
1140				Body:          body,
1141				BodyChanged:   inputs.BodyChanged,
1142				LabelAdd:      inputs.LabelAdd,
1143				LabelRemove:   inputs.LabelRemove,
1144			})
1145	
1146			// The single-trail endpoint is keyed by trail number, not id; the server
1147			// rejects an id here with "Invalid trail number format".
1148			if found.Number <= 0 {
1149				return fmt.Errorf("trail for branch %q has no number yet; cannot update", branch)
1150			}
1151			resp, err := client.Patch(ctx, trailNumberPath(forge, owner, repoName, found.Number), updateReq)
1152			if err != nil {
1153				return fmt.Errorf("failed to update trail: %w", err)
1154			}
1155			defer resp.Body.Close()
1156			if err := checkTrailResponse(resp); err != nil {
1157				return err
1158			}
1159	
1160			var updateResp api.TrailUpdateResponse
1161			if err := api.DecodeJSON(resp, &updateResp); err != nil {
1162				return fmt.Errorf("failed to decode update response: %w", err)
1163			}
1164	
1165			fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
1166			return nil
1167		})
1168	}
