1170	func validateTrailUpdateFields(inputs trailUpdateInputs) error {
1171		if inputs.TitleChanged && strings.TrimSpace(inputs.Title) == "" {
1172			return errors.New("trail title is required")
1173		}
1174		if inputs.StatusChanged {
1175			status := trail.Status(strings.TrimSpace(inputs.Status))
1176			if !status.IsValid() {
1177				return fmt.Errorf("invalid status %q: valid values are %s", inputs.Status, formatValidStatuses())
1178			}
