1183	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
1184	func buildTrailUpdateRequest(current *api.TrailResource, inputs trailUpdateInputs) api.TrailUpdateRequest {
1185		var req api.TrailUpdateRequest
1186	
1187		if inputs.StatusChanged {
1188			req.Status = &inputs.Status
1189		}
1190		if inputs.TitleChanged {
1191			req.Title = &inputs.Title
1192		}
1193		if inputs.BodyChanged {
1194			req.Body = &inputs.Body
1195		}
1196	
1197		// Handle label changes: merge adds, remove removes.
1198		if len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0 {
1199			labels := make([]string, 0, len(current.Labels)+len(inputs.LabelAdd))
1200			labels = append(labels, current.Labels...)
1201			for _, l := range inputs.LabelAdd {
1202				found := false
1203				for _, existing := range labels {
1204					if existing == l {
1205						found = true
1206						break
1207					}
1208				}
1209				if !found {
1210					labels = append(labels, l)
1211				}
1212			}
1213			for _, l := range inputs.LabelRemove {
1214				for i, existing := range labels {
1215					if existing == l {
1216						labels = append(labels[:i], labels[i+1:]...)
1217						break
1218					}
1219				}
1220			}
1221			req.Labels = &labels
1222		}
1223	
1224		return req
1225	}
