284	// noTrailDescription is shown by `trail show` when a trail's description loaded
285	// successfully but is empty — distinguishing "no description yet" from a load
286	// failure (which warns and renders nothing).
287	const noTrailDescription = "-- no description provided --"
288	
289	// trailDescriptionForDisplay returns the text `trail show` renders for the
290	// description: the body when present; the placeholder when it loaded but is
291	// empty; or "" when it couldn't be loaded (the caller has already warned).
292	func trailDescriptionForDisplay(bodyText string, loaded bool) string {
293		if strings.TrimSpace(bodyText) != "" {
294			return bodyText
295		}
296		if loaded {
297			return noTrailDescription
298		}
299		return ""
300	}
