302	// printCreatedTrail reports a newly created trail, including its browser URL
303	// (the same URL `trail show` surfaces) when one is available.
304	func printCreatedTrail(w io.Writer, t api.TrailResource, forge, owner, repo string) {
305		if t.Branch == "" {
306			fmt.Fprintf(w, "Created trail %q (ID: %s)\n", t.Title, t.ID)
307		} else {
308			fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", t.Title, t.Branch, t.ID)
309		}
310		if url := trailDisplayURL(t, forge, owner, repo); url != "" {
311			fmt.Fprintf(w, "  URL: %s\n", url)
312		}
313	}
314	
315	// trailDisplayURL returns the trail's browser URL. It prefers the canonical URL
316	// the server now returns, so the CLI tracks any route change without being
317	// updated in lockstep, and falls back to a locally constructed URL only for
318	// older servers that omit the field.
319	func trailDisplayURL(t api.TrailResource, forge, owner, repo string) string {
320		if strings.TrimSpace(t.URL) != "" {
321			return t.URL
322		}
323		if t.Number > 0 {
324			return trailWebURL(api.BaseURL(), forge, owner, repo, t.Number)
325		}
326		return ""
327	}
328	
329	// trailWebURL builds a fallback browser URL for a trail used only when the
330	// server does not supply one (older servers):
331	// <web-origin>/<forge>/<owner>/<repo>/trails/<number>. In production the web app
332	// is served from the same origin as the data API, so the API base URL doubles
333	// as the web origin. A split local-dev setup (API and frontend on different
334	// ports) would point this at the API port rather than the dev frontend.
335	func trailWebURL(base, forge, owner, repo string, number int) string {
336		return strings.TrimRight(base, "/") + "/" + forge + "/" + owner + "/" + repo + "/trails/" + strconv.Itoa(number)
337	}
