780		}
781		defer repo.Close()
782	
783		base = resolveTrailCreateBase(repo, base)
784		_, currentBranch, _ := isOnDefaultBranchRepo(repo) //nolint:errcheck // best-effort; reuse the open repo for the current branch name
785		title, body, base, branch, statusStr, err = resolveTrailCreateFields(cmd, w, title, body, base, branch, statusStr, currentBranch, noBranch)
786		if err != nil {
787			return err
788		}
789		if err := validateTrailCreateFields(ctx, title, branch, statusStr, noBranch); err != nil {
790			return err
791		}
792	
793		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
794		if err != nil {
795			return renderDataAPIAuthError(cmd.ErrOrStderr(), err)
