843	func resolveTrailCreateFields(cmd *cobra.Command, w io.Writer, title, body, base, branch, statusStr, currentBranch string, noBranch bool) (string, string, string, string, string, error) {
844		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
845		switch {
846		case interactive:
847			// Interactive flow: title → body → branch (unless branchless) → status.
848			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr, noBranch); err != nil {
849				return "", "", "", "", "", handleFormCancellation(w, "Trail creation", err)
850			}
851		case noBranch:
852			branch = ""
853		default:
854			// Non-interactive: derive missing values from provided flags. With
855			// --branch omitted, use the checked-out branch (a feature branch); only
856			// slug a new branch from the title when the checked-out branch is the base.
857			branch = resolveCreateBranch(branch, currentBranch, base, title, cmd.Flags().Changed("title"))
858			if title == "" {
859				title = trail.HumanizeBranchName(branch)
860			}
861		}
862		statusStr = strings.TrimSpace(statusStr)
863		if statusStr == "" {
864			statusStr = string(trail.StatusOpen)
865		}
866		return strings.TrimSpace(title), body, strings.TrimSpace(base), strings.TrimSpace(branch), statusStr, nil
867	}
