887	func prepareTrailCreateBranch(w, errW io.Writer, repo *git.Repository, branch, currentBranch string, noBranch bool) (trailCreateBranchState, error) {
888		var state trailCreateBranchState
889		if noBranch || branch == "" {
890			// Branchless trails have no remote branch to create, fetch, or push.
891			return state, nil
892		}
893	
894		state.NeedsCreation = branchNeedsCreation(repo, branch)
895		existedOnOrigin, existErr := branchExistsOnOrigin(branch)
896		if existErr != nil {
897			fmt.Fprintf(errW, "Warning: could not check whether branch %s already exists on origin: %v\n", branch, existErr)
898			existedOnOrigin = true
899		}
900	
901		if err := ensureTrailCreateBranchExists(w, repo, branch, currentBranch, existedOnOrigin, &state); err != nil {
902			return state, err
903		}
904	
905		// For branch-backed trails, always push the branch first: the trail binds to a
906		// remote branch, so deliver it before creating the trail rather than letting
907		// the server backfill it at the base tip. Branchless trails skip this entirely.
908		if err := pushBranchToOrigin(branch); err != nil {
909			cleanupCreatedTrailBranch(repo, branch, state.LocalCreated, false, errW)
910			return state, fmt.Errorf("failed to push branch %q to origin: %w\nhint: the trail was not created because its branch could not be delivered to the remote.\n  - if this is an auth error, link your GitHub account and retry\n  - if this is a non-fast-forward, update branch %q from origin and retry", branch, err, branch)
911		}
912		state.RemotePushed = !existedOnOrigin
913		fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
914		return state, nil
915	}
