917	func ensureTrailCreateBranchExists(w io.Writer, repo *git.Repository, branch, currentBranch string, existedOnOrigin bool, state *trailCreateBranchState) error {
918		if !state.NeedsCreation {
919			if currentBranch != branch {
920				fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
921			}
922			return nil
923		}
924		if existedOnOrigin {
925			if err := fetchBranchFromOrigin(branch); err != nil {
926				return fmt.Errorf("failed to fetch branch %q from origin: %w", branch, err)
927			}
928			state.LocalCreated = true
929			fmt.Fprintf(w, "Fetched branch %s from origin\n", branch)
930			return nil
931		}
932		if err := createBranch(repo, branch); err != nil {
933			return fmt.Errorf("failed to create branch %q: %w", branch, err)
934		}
935		state.LocalCreated = true
936		fmt.Fprintf(w, "Created branch %s\n", branch)
937		return nil
938	}
