940	func postTrailCreate(ctx context.Context, client *api.Client, forge, owner, repoName, title, body, branch, base, statusStr string) (api.TrailCreateResponse, error) {
941		createReq := newTrailCreateRequest(title, body, branch, base, statusStr)
942		resp, err := client.Post(ctx, trailsBasePath(forge, owner, repoName), createReq)
