func mergeStringSet(current, add, remove []string) []string {
	out := make([]string, 0, len(current)+len(add))
	out = append(out, current...)
	for _, a := range add {
		found := false
		for _, e := range out {
			if e == a {
				found = true
				break
			}
		}
		if !found {
			out = append(out, a)
		}
	}
	for _, r := range remove {
		for i, e := range out {
			if e == r {
				out = append(out[:i], out[i+1:]...)
